#!/usr/bin/env python3
"""The casts cactbot announces as a raidwide or a tankbuster, as RSR's shipped lists (concept 13, "Die mitgelieferten
Listen: Upstream und cactbot", A620).

RSR adds a cast to its area list only after it hit every member of a party of four or more, and learns a tankbuster
without a marker only after its first cast at the tank. Until then only a BossModReborn prediction opens the defence,
and that is missing wherever no module runs or a module does not predict the kind. cactbot (OverlayPlugin/cactbot,
Apache-2.0) announces these casts per fight; its action ids - facts of the game, no code - extend the shipped lists.

  generate <cactbot checkout>   writes RotationSolver/Basic/Resources/CactbotCasts.g.cs from ui/raidboss/data: triggers of
                                type StartsUsing (the id is the cast's, as RSR reads it on the caster) whose response is
                                Responses.aoe or bigAoe (area) or tankBuster, tankBusterSwap, sharedTankBuster, tankCleave
                                (tank). Ids upstream retired from its own list stay out.
  --check                       the file in the tree: sorted, unique, no retired id, and every id a row of the Action sheet
                                that is no player action (xivapi v2; skipped when xivapi cannot be reached).
  --self-test                   the trigger reading and the check against constructed cases.

Usage: python3 .github/scripts/audit/cactbot_casts.py generate <dir> | --check | --self-test
"""
import json
import os
import re
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[3]
OUT = ROOT / 'RotationSolver/Basic/Resources/CactbotCasts.g.cs'
CONFIG = ROOT / 'RotationSolver/Basic/Configuration/OtherConfiguration.cs'
API = 'https://v2.xivapi.com/api'

KINDS = {
    'HostileCastingArea': re.compile(r'Responses\.(?:aoe|bigAoe)\b'),
    'HostileCastingTank': re.compile(r'Responses\.(?:tankBuster|tankBusterSwap|sharedTankBuster|tankCleave)\b'),
}
TRIGGER = re.compile(r"\n    \{\n      id: '([^']*)'(.*?)\n    \},", re.S)
STARTS_USING = re.compile(r"type:\s*'StartsUsing'")
REGEX_IDS = re.compile(r"netRegex:\s*\{[^}]*?\bid:\s*(\[[^\]]*\]|'[0-9A-Fa-f]+')")
HEX_ID = re.compile(r"'([0-9A-Fa-f]{1,6})'")


def read_triggers(text):
    """{list name: set of cast ids} announced in one cactbot trigger file."""
    found = {name: set() for name in KINDS}
    for match in TRIGGER.finditer(text):
        body = match.group(2)
        if not STARTS_USING.search(body):
            continue
        ids = set()
        for group in REGEX_IDS.findall(body):
            ids.update(int(h, 16) for h in HEX_ID.findall(group))
        for name, response in KINDS.items():
            if response.search(body):
                found[name].update(ids)
    return found


def retired_ids(config_text):
    """{list name: ids upstream retired from it}, from the SetList calls in OtherConfiguration."""
    retired = {}
    for name in KINDS:
        call = re.search(r'new SetList\(nameof\(' + name + r'\),.*?v => ' + name + r' = v,?(.*?)\),\s*\n', config_text, re.S)
        retired[name] = {int(n) for n in re.findall(r'\b\d+\b', call.group(1))} if call else set()
    return retired


def collect(cactbot_dir, retired):
    lists = {name: set() for name in KINDS}
    data = Path(cactbot_dir) / 'ui/raidboss/data'
    for path in sorted(data.rglob('*.ts')):
        for name, ids in read_triggers(path.read_text(encoding='utf-8')).items():
            lists[name].update(ids)
    for name in KINDS:
        lists[name] -= retired.get(name, set())
    return lists


def render(lists, source):
    lines = [
        '// <auto-generated>',
        f'// Written by .github/scripts/audit/cactbot_casts.py from {source}; do not edit, generate it again.',
        '// </auto-generated>',
        'namespace RotationSolver.Basic.Resources;',
        '',
        '/// <summary>',
        '/// The casts cactbot announces as a raidwide or a tankbuster, shipped beside upstream\'s lists (concept 13,',
        '/// "Die mitgelieferten Listen: Upstream und cactbot", A620).',
        '/// </summary>',
        'internal static class CactbotCasts',
        '{',
    ]
    for i, name in enumerate(KINDS):
        ids = sorted(lists[name])
        lines.append(f'\tpublic static readonly uint[] {name} =')
        lines.append('\t[')
        for start in range(0, len(ids), 10):
            lines.append('\t\t' + ', '.join(str(x) for x in ids[start:start + 10]) + ',')
        lines.append('\t];')
        if i < len(KINDS) - 1:
            lines.append('')
    lines.append('}')
    return '\n'.join(lines) + '\n'


def parse_generated(text):
    lists = {}
    for name in KINDS:
        match = re.search(r'uint\[\] ' + name + r' =\s*\[(.*?)\];', text, re.S)
        lists[name] = [int(n) for n in re.findall(r'\b\d+\b', match.group(1))] if match else None
    return lists


def fetch_json(url):
    """The parsed answer, or None when xivapi cannot be reached (curl: the proxy setup is configured for it)."""
    try:
        out = subprocess.run(['curl', '-sS', '--max-time', '30', url], capture_output=True, text=True)
        return json.loads(out.stdout) if out.returncode == 0 and out.stdout else None
    except (OSError, ValueError):
        return None


def sheet_rows(ids, fetch):
    """{row id: is a player action} for the ids, or None when xivapi cannot be reached."""
    rows = {}
    ordered = sorted(ids)
    for start in range(0, len(ordered), 100):
        part = ordered[start:start + 100]
        answer = fetch(f'{API}/sheet/Action?rows={",".join(map(str, part))}&fields=IsPlayerAction')
        if answer is None:
            return None
        for row in answer.get('rows', []):
            rows[row['row_id']] = bool(row['fields'].get('IsPlayerAction'))
    return rows


def problems(lists, retired, rows):
    found = []
    for name, ids in lists.items():
        if ids is None:
            found.append(f'{name}: list missing from the generated file')
            continue
        if ids != sorted(set(ids)):
            found.append(f'{name}: ids not sorted and unique')
        for x in sorted(set(ids) & retired.get(name, set())):
            found.append(f'{name}: {x} is retired upstream')
        if rows is not None:
            for x in ids:
                if x not in rows:
                    found.append(f'{name}: {x} is no row of the Action sheet')
                elif rows[x]:
                    found.append(f'{name}: {x} is a player action')
    return found


def check(fetch=fetch_json):
    lists = parse_generated(OUT.read_text(encoding='utf-8'))
    retired = retired_ids(CONFIG.read_text(encoding='utf-8'))
    every = set()
    for ids in lists.values():
        every.update(ids or [])
    rows = sheet_rows(every, fetch)
    found = problems(lists, retired, rows)
    for p in found:
        print(p)
    if rows is None:
        print('xivapi is not reachable: the ids were not held against the Action sheet this run.')
    if not found:
        print(f'{OUT.relative_to(ROOT)}: ' + ', '.join(f'{n} {len(v or [])}' for n, v in lists.items())
              + ' cast(s), sorted, unique, none retired' + ('' if rows is None else ', every one an enemy action of the Action sheet') + '.')
    return 1 if found else 0


def self_test():
    sample = (
        "\n    {\n      id: 'A Raidwide',\n      type: 'StartsUsing',\n      netRegex: { id: '9576', source: 'X', capture: false },\n"
        "      response: Responses.aoe(),\n    },"
        "\n    {\n      id: 'A Buster',\n      type: 'StartsUsing',\n      netRegex: { id: ['9575', 'A941'], source: 'X' },\n"
        "      response: Responses.tankBuster(),\n    },"
        "\n    {\n      id: 'A Damage Line',\n      type: 'Ability',\n      netRegex: { id: '1234', source: 'X' },\n"
        "      response: Responses.aoe(),\n    },"
        "\n    {\n      id: 'A Spread',\n      type: 'StartsUsing',\n      netRegex: { id: '5678', source: 'X' },\n"
        "      response: Responses.spread(),\n    },"
    )
    found = read_triggers(sample)
    assert found['HostileCastingArea'] == {0x9576}, found
    assert found['HostileCastingTank'] == {0x9575, 0xA941}, found
    config = ("new SetList(nameof(HostileCastingArea), ActionLists.HostileCastingArea, () => HostileCastingArea, v => HostileCastingArea = v, 41147, 41763),\n"
              "new SetList(nameof(HostileCastingTank), ActionLists.HostileCastingTank, () => HostileCastingTank, v => HostileCastingTank = v,\n"
              "\t13364, 13365),\n")
    retired = retired_ids(config)
    assert retired == {'HostileCastingArea': {41147, 41763}, 'HostileCastingTank': {13364, 13365}}, retired
    text = render({'HostileCastingArea': {3, 2, 41147}, 'HostileCastingTank': {5}}, 'test')
    lists = parse_generated(text)
    assert lists == {'HostileCastingArea': [2, 3, 41147], 'HostileCastingTank': [5]}, lists
    assert problems(lists, retired, {2: False, 3: False, 41147: False, 5: False}) == ['HostileCastingArea: 41147 is retired upstream']
    assert problems({'HostileCastingArea': [3, 2], 'HostileCastingTank': [5]}, {}, None) == ['HostileCastingArea: ids not sorted and unique']
    assert problems({'HostileCastingArea': [2], 'HostileCastingTank': [5]}, {}, {2: True}) == [
        'HostileCastingArea: 2 is a player action', 'HostileCastingTank: 5 is no row of the Action sheet']
    print('self-test ok: StartsUsing triggers with an area or tankbuster response are read, other types and responses are '
          'not; retired ids are found in both call forms; the file round-trips; unsorted, retired, missing and player-action '
          'ids are reported')
    return 0


def main(argv):
    if argv[:1] == ['--self-test']:
        return self_test()
    if argv[:1] == ['--check']:
        return check()
    if len(argv) == 2 and argv[0] == 'generate':
        cactbot = Path(argv[1])
        commit = subprocess.run(['git', '-C', str(cactbot), 'log', '-1', '--format=%h %cs'], capture_output=True, text=True).stdout.strip()
        retired = retired_ids(CONFIG.read_text(encoding='utf-8'))
        lists = collect(cactbot, retired)
        OUT.write_text(render(lists, f'OverlayPlugin/cactbot {commit}'), encoding='utf-8')
        print(f'{OUT.relative_to(ROOT)}: ' + ', '.join(f'{n} {len(v)}' for n, v in lists.items()))
        return 0
    print(__doc__)
    return 2


if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))
